package com.hbm.client.gascentrifuge;
import com.hbm.machine.gascentrifuge.*;import mezz.jei.api.*;import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.IGuiHelper;import mezz.jei.api.recipe.*;import mezz.jei.api.recipe.category.IRecipeCategory;import mezz.jei.api.registration.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemStack;
@JeiPlugin public final class GasCentrifugeJeiPlugin implements IModPlugin {
 static final RecipeType<GasCentrifugeRecipe> TYPE=RecipeType.create("hbm","gascentrifuge",GasCentrifugeRecipe.class);@Override public ResourceLocation getPluginUid(){return GasCentrifugeContent.id("gascentrifuge_jei");}@Override public void registerCategories(IRecipeCategoryRegistration event){event.addRecipeCategories(new Category(event.getJeiHelpers().getGuiHelper()));}@Override public void registerRecipes(IRecipeRegistration event){var level=Minecraft.getInstance().level;if(level!=null)event.addRecipes(TYPE,GasCentrifugeRecipes.recipes(level.getRecipeManager()));}@Override public void registerRecipeCatalysts(IRecipeCatalystRegistration event){event.addRecipeCatalysts(TYPE,GasCentrifugeContent.ITEM.get());}@Override public void registerGuiHandlers(IGuiHandlerRegistration event){event.addRecipeClickArea(GasCentrifugeScreen.class,65,25,36,12,TYPE);}
 private static final class Category implements IRecipeCategory<GasCentrifugeRecipe>{private final IDrawable background,icon;Category(IGuiHelper helper){background=helper.createBlankDrawable(166,65);icon=helper.createDrawableItemStack(new ItemStack(GasCentrifugeContent.ITEM.get()));}@Override public RecipeType<GasCentrifugeRecipe> getRecipeType(){return TYPE;}@Override public Component getTitle(){return Component.translatable("container.gasCentrifuge");}@Override public IDrawable getBackground(){return background;}@Override public IDrawable getIcon(){return icon;}@Override public void setRecipe(IRecipeLayoutBuilder builder,GasCentrifugeRecipe recipe,IFocusGroup focus){builder.addSlot(RecipeIngredientRole.INPUT,47,24).addItemStack(recipe.input());builder.addSlot(RecipeIngredientRole.CATALYST,3,42).addItemStacks(GasCentrifugeViews.batteries());for(int i=0;i<recipe.results().size();i++){var p=GasCentrifugeViews.output(i);builder.addSlot(RecipeIngredientRole.OUTPUT,p[0],p[1]).addItemStack(recipe.results().get(i));}}@Override public void draw(GasCentrifugeRecipe recipe,IRecipeSlotsView slots,GuiGraphics graphics,double x,double y){GasCentrifugeViews.draw(recipe,graphics,0,0);}}
}
